## ${r.record.unit} / ${r.record.item}
${r.record.status}: ${r.record.summary}
${r.record.issues.map(i=>'- '+i).join('
')}
Evidence: ${r.record.evidence.map(e=>e.path).join(', ')}`)].join('
');
  fs.writeFileSync(path.join(ROOT,'docs/factory/project/FINAL_VISUAL_AUDIT.md'),report+'
');
  fs.writeFileSync(path.join(ROOT,'docs/factory/project/FINAL_REPORT.md'),report+'
');
  write(path.join(path.dirname(inside(ROOT,file)),'result.json'),result);
