// temu, co bÄ™dziesz obsÅ‚ugiwaÄ‡ niÅ¼ej w @each w mixinie.
$scale-factors: (
    xl-max:  0.9,
    lg-max:  0.8,
    md-max:  0.7,
    sm-max:  0.6,
    xs-max:  0.5
