// JeÅ›li chcesz, moÅ¼esz tu zdecydowaÄ‡, jaki wspÃ³Å‚czynnik
// line-height przyjmiesz: np. 1.3, 1.4 etc.
$default-line-height-factor: 1.3;

// Funkcja do clampowania rozmiaru:
@function clamp-font-size($value, $min: 16) {
    @return if($value < $min, $min, $value);
}
  
@mixin generate-text-classes(
    $class-prefix,
    $xl-min-values,  // np. (100: 130, 80: 104, 50: 65)
    $scale-factors   // np. (xl-max: 0.9, lg-max: 0.8, md-max: 0.7, ...)
) {
    $text-values: ();

    @each $base-font-size, $base-line-height in $xl-min-values {
    // Wylicz wspÃ³Å‚czynnik line-height
    // @debug "Font size: #{$base-font-size}, Line height: #{$base-line-height}";
    $ratio: calc($base-line-height / $base-font-size);

    // Zaczynamy budowaÄ‡ mapÄ™ breakpointÃ³w 
    // i clampujemy juÅ¼ w tym kroku
    $bp-sizes: (
        xl-min: clamp-font-size($base-font-size)
    );

    @each $bp, $factor in $scale-factors {
        $scaled-size: $base-font-size * $factor;
        $bp-sizes: map-merge(
        $bp-sizes,
        (
            $bp: clamp-font-size($scaled-size)
        )
        );
    }

    $text-values: map-merge(
        $text-values,
        (
        $base-font-size: (
            ratio: $ratio,
            breakpoints: $bp-sizes
        )
        )
